package com.mohymods.kingdomsmp.economy;
import static org.junit.jupiter.api.Assertions.*;
import com.mohymods.kingdomsmp.profession.*;
import com.mohymods.kingdomsmp.persistence.AtomicNbt;
import java.util.*;
import java.nio.file.Path;
import java.io.IOException;
import net.minecraft.nbt.CompoundTag;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
class LibraryJourneymanStoreTest {
 @TempDir Path directory;UUID p=UUID.randomUUID();
 static CompoundTag book(int n){var item=new CompoundTag();item.putString("id","minecraft:enchanted_book");item.putInt("count",1);var comp=new CompoundTag();comp.putInt("minecraft:repair_cost",n);item.put("components",comp);return item;}
 EconomyStore earnedApprentice()throws Exception{var s=EconomyStore.open(directory);s.changeProfession(UUID.randomUUID(),p,"enroll","","librarian");var material=s.prepareProfessionDelivery(UUID.randomUUID(),p,CraftDeliveryQuests.LIBRARY_BOOKS,"Pure canonical earlier native books boundary",CraftDeliveryQuests.defaults(CraftDeliveryQuests.LIBRARY_BOOKS));s.recoverItem(new EconomyStore.Receipt(s.id(),material.sequence()));for(var q:List.of("a02","a03"))s.approveProfessionInspection(UUID.randomUUID(),UUID.randomUUID(),p,"kingdom_smp:librarian/"+q,"Pure canonical earlier approved inspection model");for(var q:List.of(NativeOutputQuests.LIBRARY_ENCHANT,NativeOutputQuests.LIBRARY_BOOKS)){Map<UUID,CompoundTag> items=new HashMap<>();for(int n=0;n<4;n++){var id=UUID.randomUUID();var b=book(n);s.issueNativeOutput(id,p,q,b);items.put(id,b);}var pending=s.prepareNativeOutputDelivery(UUID.randomUUID(),p,q,items,4);s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));}var paper=new CompoundTag();paper.putString("id","minecraft:paper");paper.putInt("count",1);for(long day=1;day<=3;day++){var q=s.prepareContract(UUID.randomUUID(),p,"librarian","daily",day,32,16,2000,paper,4);s.recoverItem(new EconomyStore.Receipt(s.id(),q.sequence()));}s.completeCommissionQuest(UUID.randomUUID(),p,"kingdom_smp:librarian/a07",3);for(var q:List.of("a06","a08"))s.approveProfessionInspection(UUID.randomUUID(),UUID.randomUUID(),p,"kingdom_smp:librarian/"+q,"Pure canonical actual earlier assessment boundary");assertEquals(800,s.professions(p).track(Profession.LIBRARIAN).xp());return s;}
 @Test void familiesRejectMonocultureAndUseDistinctNativeFactsWithAtomicRecovery()throws Exception{var s=earnedApprentice();Map<UUID,CompoundTag> wrong=new HashMap<>(),good=new HashMap<>();for(int n=0;n<4;n++){var id=UUID.randomUUID();var b=book(n);s.issueNativeOutput(id,p,NativeOutputQuests.LIBRARY_FAMILIES,b,new NativeBookProof(2,false));wrong.put(id,b);var valid=UUID.randomUUID();s.issueNativeOutput(valid,p,NativeOutputQuests.LIBRARY_FAMILIES,b,new NativeBookProof(1<<n,false));good.put(valid,b);}assertThrows(IllegalStateException.class,()->s.prepareNativeOutputDelivery(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_FAMILIES,wrong,4));var pending=s.prepareNativeOutputDelivery(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_FAMILIES,good,4);assertFalse(s.recoverItem(new EconomyStore.Receipt(s.id(),s.expectedReceipt(p))));var q=s.prepareNativeOutputDelivery(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_FAMILIES,good,4);var fault=EconomyStore.open(directory,(file,data)->{AtomicNbt.write(file,data);throw new IOException("Native family receipt after rename");});assertThrows(IOException.class,()->fault.recoverItem(new EconomyStore.Receipt(s.id(),q.sequence())));var restored=EconomyStore.open(directory);assertFalse(restored.recoverItem(new EconomyStore.Receipt(s.id(),q.sequence())));good.forEach((id,b)->assertTrue(restored.nativeOutputAttributes(id,p,NativeOutputQuests.LIBRARY_FAMILIES,b).isEmpty()));assertEquals(1000,restored.professions(p).track(Profession.LIBRARIAN).xp());restored.archive(p,"Native family model recovery");assertEquals(1000,EconomyStore.open(directory).professions(p).track(Profession.LIBRARIAN).xp());}
 @Test void maximumCommissionIsIndependentOfFamilyQuestAndRequiresPositiveNativeFacts()throws Exception{var s=earnedApprentice();assertThrows(IllegalArgumentException.class,()->s.issueNativeOutput(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_MAXIMUM,book(1)));Map<UUID,CompoundTag> items=new HashMap<>();for(int n=0;n<2;n++){var id=UUID.randomUUID();var b=book(n);s.issueNativeOutput(id,p,NativeOutputQuests.LIBRARY_MAXIMUM,b,new NativeBookProof(8,true));items.put(id,b);assertFalse(s.matchesNativeOutput(id,p,NativeOutputQuests.LIBRARY_FAMILIES,b));}var q=s.prepareNativeOutputDelivery(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_MAXIMUM,items,2);s.recoverItem(new EconomyStore.Receipt(s.id(),q.sequence()));assertEquals(1000,s.professions(p).track(Profession.LIBRARIAN).xp());assertFalse(s.professions(p).track(Profession.LIBRARIAN).completedQuestIds().contains(NativeOutputQuests.LIBRARY_FAMILIES));assertThrows(IllegalStateException.class,()->s.prepareNativeOutputDelivery(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_MAXIMUM,items,2));assertEquals(s.professions(p),EconomyStore.open(directory).professions(p));}
}
